def parse(raw, prefix):
 out=[]
 for i,line in enumerate(raw.splitlines(),1):
  form,meaning,syntax,ko,uz,note=line.split('|')
  out.append(dict(id=f'{prefix}{i:02}',form=form,meaning=meaning,syntax=syntax,ko=ko,uz=uz,note=note))
 return out
A=parse(A_RAW,'A'); B=parse(B_RAW,'B')
